import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
def nm(pred): return np.mean((pred-y)**2)/np.var(y)
models={
 'A: a+b t + c P^d + e t P^f': (lambda p: p[0]+p[1]*t+p[2]*P**p[3]+p[4]*t*P**p[5], 6),
 'B: a + bP^c + (d+eP) t + f t^2': (lambda p: p[0]+p[1]*P**p[2]+(p[3]+p[4]*P)*t+p[5]*t**2, 6),
 'C: a P^b + c t + d t P + e exp(f t)*P ': (lambda p: p[0]*P**p[1]+p[2]*t+p[3]*t*P+p[4]*np.exp(p[5]*t)*P+p[6], 7),
 'D: (a+bt)P^c + d + e t P': (lambda p: (p[0]+p[1]*t)*P**p[2]+p[3]+p[4]*t*P, 5),
 'E: a/P^c + d*t + e*tP + f': (lambda p: p[0]/P**p[1]+p[2]*t+p[3]*t*P+p[4]+p[5]*P, 6),
}
rng=np.random.default_rng(0)
for name,(f,n) in models.items():
    best=(1e9,None)
    for trial in range(30):
        p0=rng.uniform(-1,1,n); p0[-1]=abs(p0[-1])*2 if 'C' in name else p0[-1]
        try:
            r=least_squares(lambda p: f(p)-y, p0, max_nfev=2000)
            v=nm(f(r.x))
            if np.isfinite(v) and v<best[0]: best=(v,r.x)
        except Exception as e: pass
    print(name, '%.3e'%best[0], np.round(best[1],4))
